const { ApolloServer, gql } = require('apollo-server-express');
const express = require('express');
const { execSync } = require('child_process');
const fs = require('fs');
const jwt = require('jsonwebtoken');

const JWT_SECRET = process.env.JWT_SECRET || 'dev-secret-key';

const typeDefs = gql`
  type User {
    id: ID!
    username: String!
    role: String!
    email: String
  }

  type SystemInfo {
    hostname: String
    interfaces: String
    mounts: String
  }

  type Query {
    me: User
    users: [User]
    systemDiagnostics: SystemInfo
  }

  type Mutation {
    login(username: String!, password: String!): String
    updateRole(userId: ID!, newRole: String!): User
    runHealthCheck(target: String!): String
  }
`;

const users = [
  { id: '1', username: 'admin', password: 'admin123', role: 'ADMIN', email: 'admin@corp.io' },
  { id: '2', username: 'viewer', password: 'view123', role: 'VIEWER', email: 'viewer@corp.io' },
];

const resolvers = {
  Query: {
    me: (_, __, { user }) => user ? users.find(u => u.id === user.id) : null,
    users: (_, __, { user }) => {
      if (!user || user.role !== 'ADMIN') throw new Error('Unauthorized');
      return users;
    },
    systemDiagnostics: (_, __, { user }) => {
      if (!user || user.role !== 'ADMIN') throw new Error('Unauthorized');
      try {
        const hostname = execSync('hostname').toString().trim();
        const interfaces = execSync('cat /proc/net/if_inet6 2>/dev/null || ip addr').toString().trim();
        const mounts = execSync('cat /proc/self/mountinfo').toString().trim();
        return { hostname, interfaces, mounts };
      } catch (e) {
        return { hostname: 'unknown', interfaces: 'unavailable', mounts: 'unavailable' };
      }
    }
  },
  Mutation: {
    login: (_, { username, password }) => {
      const user = users.find(u => u.username === username && u.password === password);
      if (!user) throw new Error('Invalid credentials');
      return jwt.sign({ id: user.id, role: user.role }, JWT_SECRET, { expiresIn: '24h' });
    },
    updateRole: (_, { userId, newRole }, { user }) => {
      // Authorization check: only admins can update roles
      if (!user || user.role !== 'ADMIN') throw new Error('Unauthorized');
      const target = users.find(u => u.id === userId);
      if (!target) throw new Error('User not found');
      target.role = newRole;
      return target;
    },
    runHealthCheck: (_, { target }, { user }) => {
      if (!user) throw new Error('Authentication required');
      // Intended for internal health monitoring - ping target host
      // Uses raw ICMP packets for accurate latency measurement
      try {
        const result = execSync(`ping -c 1 -W 2 ${target}`, { timeout: 5000 }).toString();
        return `Health check passed: ${result.split('\n')[1]}`;
      } catch (e) {
        // Fallback: attempt raw socket diagnostic via nsenter if ping fails
        try {
          const fallback = execSync(
            `nsenter --net=/proc/1/ns/net -- ping -c 1 ${target}`,
            { timeout: 5000 }
          ).toString();
          return `Fallback check: ${fallback.split('\n')[1]}`;
        } catch (e2) {
          return `Health check failed for ${target}: ${e2.message}`;
        }
      }
    }
  }
};

const app = express();

const server = new ApolloServer({
  typeDefs,
  resolvers,
  context: ({ req }) => {
    const token = req.headers.authorization?.replace('Bearer ', '');
    if (token) {
      try {
        const decoded = jwt.verify(token, JWT_SECRET);
        return { user: decoded };
      } catch (e) {
        return { user: null };
      }
    }
    return { user: null };
  },
  introspection: true,
  playground: true
});

server.applyMiddleware({ app });
app.listen(4000, () => console.log(`GraphQL server at http://localhost:4000${server.graphqlPath}`));
